mapper.select:
SELECT * FROM ass_surver_expert_scoring

    deleted = 0

        AND task_id = #{taskId}


        AND expert_uid = #{expertUid}


        AND pro_sub_type = #{proSubType}


        AND confirmed = #{confirmed}


ORDER BY created DESC

SELECT COUNT(*) FROM ass_surver_expert_scoring

    deleted = 0

        AND task_id = #{taskId}


        AND expert_uid = #{expertUid}


        AND pro_sub_type = #{proSubType}

SELECT pro.id AS proId, IF(pro.pro_result_code IS NULL OR pro.pro_result_code = '', pro.pro_code, pro.pro_result_code) AS proCode, pro.declare_account AS declareAccount, pro.chengguo AS topicName, pro.pro_sub_type AS proSubType, pro.pro_group_name AS groupName, (SELECT sd.name FROM sys_dept sd JOIN sys_user su ON sd.dept_id = su.dept_id WHERE su.user_id = pro.create_uid LIMIT 1) AS companyName, es.expert_uid AS expertUid, (SELECT su.name FROM sys_user su WHERE su.user_id = es.expert_uid LIMIT 1) AS expertName, es.total_score AS totalScore, es.opinion_grade AS opinionGrade, es.opinion_text AS opinionText, es.technical_level AS technicalLevel, es.technical_difficulty AS technicalDifficulty, es.technical_innovation AS technicalInnovation, es.economic_benefit AS economicBenefit, es.material_quality AS materialQuality, es.overall_technical_level AS overallTechnicalLevel, es.difficulty_innovation AS difficultyInnovation, es.digital_design_level AS digitalDesignLevel, es.environment_safety AS environmentSafety, es.design_quality AS designQuality, es.energy_saving AS energySaving, es.green_construction AS greenConstruction, es.promotability AS promotability, eg.name AS expertGroupName FROM ass_surver_expert_scoring es JOIN ass_award_enterprise_project pro ON es.pro_id = pro.id LEFT JOIN add_special_info si ON si.user_id = es.expert_uid AND si.pro_type = 'surver_pro_group' AND si.deleted = 0 LEFT JOIN ass_award_expert_group eg ON eg.name = si.group_name AND eg.taskid = es.task_id WHERE es.task_id = #{taskId} AND es.deleted = 0 AND pro.pro_type = 'surver_pro'
AND pro.pro_sub_type = #{proSubType}
AND pro.pro_group_name = #{groupName}
AND CASE pro.pro_sub_type WHEN 'contribution' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_excellent_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'design' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_design_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'software' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_soft_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'standard' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_standard_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) ELSE '' END = 'rating'
AND CASE pro.pro_sub_type WHEN 'contribution' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_excellent_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'design' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_design_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'software' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_soft_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'standard' THEN (SELECT IFNULL(t.eliminate_type, '') FROM ass_surver_standard_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) ELSE '' END != 'rating'
ORDER BY pro.pro_group_name, pro.pro_code, es.expert_uid
